from __future__ import annotations

import math
import time
from dataclasses import asdict, dataclass

import numpy as np
import torch

from . import cells_C as CC

B, E = CC.B, CC.E


DT = torch.float64

def zoh_basis(log_I, log_c, t_force, tau, t_s, query):
    """expB_cells.zoh_basis copied verbatim except that the two scalar tensors are created on t_force's device
    (the original always creates them on the CPU, which only works for CPU training as in MLP-SS).
    tests_MJ.py checks bitwise equality with the original on the CPU."""
    I, c = torch.exp(log_I)[..., None], torch.exp(log_c)[..., None]
    a = c / I
    k = int(torch.searchsorted(t_force, torch.as_tensor(t_s, dtype=DT, device=t_force.device), right=True)) - 1
    after = t_force > t_s
    knots = torch.cat([torch.as_tensor([t_s], dtype=DT, device=t_force.device), t_force[after]])
    held = torch.cat([tau[max(k, 0):max(k, 0) + 1], tau[after]])            # held[j] on [knots_j, knots_j+1)
    h = torch.diff(knots)
    vinf = held / c                                                          # [B, K]
    e = torch.exp(-a * h)
    ah = a * h
    phi = torch.where(ah > 1e-6, (1 - e) / a, h * (1 - 0.5 * ah))
    v = torch.zeros_like(a[..., 0]); q = torch.zeros_like(a[..., 0])
    qs, vs = [q], [v]
    for j in range(h.numel()):
        q = q + vinf[..., j] * h[j] + (v - vinf[..., j]) * phi[..., j]
        v = vinf[..., j] + (v - vinf[..., j]) * e[..., j]
        qs.append(q); vs.append(v)
    Q, V = torch.stack(qs, -1), torch.stack(vs, -1)
    idx = torch.clamp(torch.searchsorted(knots, query, right=True) - 1, 0, knots.numel() - 1)
    dt = query - knots[idx]
    vq = held[..., idx] / c if held.dim() > 1 else held[idx] / c
    eq = torch.exp(-a * dt)
    phiq = torch.where(a * dt > 1e-6, (1 - eq) / a, dt * (1 - 0.5 * a * dt))
    forced = Q[..., idx] + vq * dt + (V[..., idx] - vq) * phiq
    tq = query - t_s
    free = torch.where(a * tq > 1e-6, (1 - torch.exp(-a * tq)) / a, tq * (1 - 0.5 * a * tq))
    return forced, free

@dataclass(frozen=True)
class Config:
    noise: str = "mixture"            # none | white | ar1 | mixture
    lambda_phys: float = 1.0
    rho_max: float = 0.95
    n_partitions: int = 4
    window: int = 3                   # local window half-width of the motion head
    motion_hidden: int = 128
    n_synth: int = 40000              # identical budget to MLP-SS
    epochs: int = 400
    batch: int = 512
    lr: float = 1e-3
    weight_decay: float = 1e-5
    patience: int = 40

def _clean(tf, tau, tq, n, gen):
    U = lambda lo, hi: lo + (hi - lo) * torch.rand(n, generator=gen, dtype=DT)
    P = B.MLP_PRIOR
    lI = U(*P["log10_inertia"]) * math.log(10)
    lc = lI - U(*P["log10_decay_time_s"]) * math.log(10)
    u_v0 = U(*P["v0_fraction_of_max_forced_velocity"])
    t_s = float(tq[0])
    tdense = torch.linspace(t_s, float(tq[-1]), 400, dtype=DT)
    qs = []
    for i in range(0, n, 2000):
        sl = slice(i, i + 2000)
        forced, free = zoh_basis(lI[sl], lc[sl], tf, tau, t_s, tq)
        fd, _ = zoh_basis(lI[sl], lc[sl], tf, tau, t_s, tdense)
        vmax = (torch.diff(fd, dim=-1) / torch.diff(tdense)).abs().amax(-1)
        qs.append(forced + (u_v0[sl] * vmax)[:, None] * free)
    return torch.cat(qs), lI, lc

def _noise(q, family, rho_max, gen):
    n, N = q.shape
    U = lambda lo, hi: lo + (hi - lo) * torch.rand(n, generator=gen, dtype=DT)
    rel = 10 ** U(*B.MLP_PRIOR["log10_rel_noise"])
    rng = q.amax(-1) - q.amin(-1)
    if family == "mixture":
        fam = torch.randint(0, 3, (n,), generator=gen)            # 0 none, 1 white, 2 ar1
    else:
        fam = torch.full((n,), {"none": 0, "white": 1, "ar1": 2}[family])
    rho = U(0.0, rho_max) * (fam == 2)
    e = torch.randn((n, N), generator=gen, dtype=DT)
    x = torch.empty_like(e)
    x[:, 0] = e[:, 0]
    a, b = rho, torch.sqrt(1 - rho ** 2)
    for i in range(1, N):                                         # rho = 0 rows reduce to white noise
        x[:, i] = a * x[:, i - 1] + b * e[:, i]
    return x * (rel * rng * (fam > 0))[:, None], fam, rho, rel

def synth_training_q(tf, tau, tq, n, cfg, gen):
    """Noisy synthetic q ONLY (training path): parameters, family and rho stay local."""
    q, _, _ = _clean(tf, tau, tq, n, gen)
    eps, _, _, _ = _noise(q, cfg.noise, cfg.rho_max, gen)
    return q + eps

def synth_validation(tf, tau, tq, n, family, rho_max, gen):
    """Validation/diagnostic path ONLY (synthetic truth; never used for training or by an object fit)."""
    q, lI, lc = _clean(tf, tau, tq, n, gen)
    eps, fam, rho, rel = _noise(q, family, rho_max, gen)
    return dict(q_clean=q, q_obs=q + eps, log_I=lI, log_c=lc, family=fam, rho=rho, rel=rel)

class Context:
    def __init__(self, tf, tau, tq, cfg: Config):
        self.tf, self.tau, self.tq = tf.to(DT), tau.to(DT), tq.to(DT)
        self.t_s = float(tq[0])
        self.tfc, self.tauc = CC.compress_zoh(self.tf, self.tau)
        tu = float(tq[-1] - tq[0])
        fu = float(self.tau.abs().max())
        self.log_ref = math.log(fu * tu * tu)
        self.lo_T, self.hi_T = (x * math.log(10) for x in B.MLP_PRIOR["log10_decay_time_s"])
        self.lo_I, self.hi_I = (x * math.log(10) for x in B.MLP_PRIOR["log10_inertia"])
        N = len(tq)
        self.N = N
        k = torch.clamp(torch.searchsorted(self.tf, self.tq, right=True) - 1, min=0)
        self.tau_obs = (self.tau[k] / fu).float()                       # ZOH effort at t_i, normalized
        self.s = (2 * (self.tq - self.tq[0]) / tu - 1).float()          # normalized time
        # partition fill tables: fill_i = (1 - w_i) q[L_i] + w_i q[R_i]
        self.L, self.R, self.W, self.masks = [], [], [], []
        idx = np.arange(N)
        t = self.tq.numpy()
        for p in range(cfg.n_partitions):
            m = (idx % cfg.n_partitions) == p
            keep = idx[~m]
            Lp, Rp, Wp = idx.copy(), idx.copy(), np.zeros(N)
            for i in idx[m]:
                left, right = keep[keep < i], keep[keep > i]
                if len(left) and len(right):
                    l, r = left[-1], right[0]
                    Lp[i], Rp[i], Wp[i] = l, r, (t[i] - t[l]) / (t[r] - t[l])
                else:
                    Lp[i] = Rp[i] = (left[-1] if len(left) else right[0])
            self.L.append(torch.as_tensor(Lp)); self.R.append(torch.as_tensor(Rp))
            self.W.append(torch.as_tensor(Wp, dtype=DT)); self.masks.append(torch.as_tensor(m))
        off = torch.arange(-cfg.window, cfg.window + 1)
        self.win = torch.clamp(torch.arange(N)[:, None] + off[None, :], 0, N - 1)   # [N, 2w+1]

    def to(self, device):
        for k in ("tfc", "tauc", "tq", "tau_obs", "s", "win"):
            setattr(self, k, getattr(self, k).to(device))
        self.L = [x.to(device) for x in self.L]; self.R = [x.to(device) for x in self.R]
        self.W = [x.to(device) for x in self.W]; self.masks = [x.to(device) for x in self.masks]
        return self

    def fill(self, q, p):
        return (1 - self.W[p]) * q[:, self.L[p]] + self.W[p] * q[:, self.R[p]]

class MLPJoint(torch.nn.Module):
    def __init__(self, n, cfg: Config):
        super().__init__()
        nn = torch.nn
        self.trunk = nn.Sequential(nn.Linear(n, 256), nn.SiLU(), nn.Linear(256, 256), nn.SiLU(), nn.Linear(256, 128), nn.SiLU())
        self.par = nn.Linear(128, 2)
        d_in = 128 + 2 + (2 * cfg.window + 1)
        self.mot = nn.Sequential(nn.Linear(d_in, cfg.motion_hidden), nn.SiLU(), nn.Linear(cfg.motion_hidden, cfg.motion_hidden),
                                 nn.SiLU(), nn.Linear(cfg.motion_hidden, 1))
        torch.nn.init.zeros_(self.mot[-1].weight)       # initial q_hat = J-invariant fill (no correction learned yet)
        torch.nn.init.zeros_(self.mot[-1].bias)

    def params(self, ctx, q):
        u, logs = E._features(q)
        o = self.par(self.trunk(u.float()))
        log_T = 0.5 * (ctx.lo_T + ctx.hi_T) + 0.5 * (ctx.hi_T - ctx.lo_T) * torch.tanh(o[:, 0].double())
        log_I = (o[:, 1].double() + ctx.log_ref - logs).clamp(ctx.lo_I, ctx.hi_I)
        return log_I, log_I - log_T

    def motion(self, ctx, q, zero_tau=False, shuffle_time=False):
        """q_hat [B, N]: each sample from the partition that masked it (J-invariant)."""
        Bn, N = q.shape
        qhat = torch.empty_like(q)
        tau = torch.zeros_like(ctx.tau_obs) if zero_tau else ctx.tau_obs
        s = ctx.s[torch.randperm(N, device=q.device)] if shuffle_time else ctx.s
        for p in range(len(ctx.masks)):
            qf = ctx.fill(q, p)
            u, logs = E._features(qf)
            z = self.trunk(u.float())                                                 # [B, 128]
            feats = torch.cat([z[:, None, :].expand(Bn, N, z.shape[1]),
                               s[None, :, None].expand(Bn, N, 1), tau[None, :, None].expand(Bn, N, 1),
                               u.float()[:, ctx.win]], -1)
            d = self.mot(feats)[..., 0].double()                                       # residual, feature units
            qp = qf + torch.exp(logs)[:, None] * d
            m = ctx.masks[p]
            qhat[:, m] = qp[:, m]
        return qhat

def project(ctx, log_I, log_c, x):
    forced, free = zoh_basis(log_I, log_c, ctx.tfc, ctx.tauc, ctx.t_s, ctx.tq)
    off, v0 = B._ls_offset_velocity(forced, free, x)
    return off[:, None] + v0[:, None] * free + forced

def losses(model, ctx, q, cfg):
    rng = (q.amax(-1) - q.amin(-1)).clamp_min(1e-30)[:, None]
    lI, lc = model.params(ctx, q)
    qhat = model.motion(ctx, q)
    L_par = (((project(ctx, lI, lc, q) - q) / rng) ** 2).mean()
    L_obs = (((qhat - q) / rng) ** 2).mean()
    L_phys = (((qhat - project(ctx, lI, lc, qhat)) / rng) ** 2).mean()
    total = L_par + L_obs + cfg.lambda_phys * L_phys
    return total, dict(par=float(L_par), obs=float(L_obs), phys=float(L_phys), total=float(total))

def train(tf, tau, tq, cfg: Config, seed: int, device: str = "cpu", log_every: int = 0):
    started = time.perf_counter()
    gen = torch.Generator().manual_seed(seed)
    ctx = Context(tf.cpu(), tau.cpu(), tq.cpu(), cfg)
    q = synth_training_q(ctx.tf, ctx.tau, ctx.tq, cfg.n_synth, cfg, gen)
    keep = torch.isfinite(q).all(-1) & ((q.amax(-1) - q.amin(-1)) > 0)
    q = q[keep]
    n_val = len(q) // 5
    perm = torch.randperm(len(q), generator=gen)
    va, tr = perm[:n_val], perm[n_val:]
    ctx.to(device)
    q = q.to(device)
    torch.manual_seed(seed)
    model = MLPJoint(ctx.N, cfg).to(device)
    opt = torch.optim.AdamW(model.parameters(), lr=cfg.lr, weight_decay=cfg.weight_decay)
    sched = torch.optim.lr_scheduler.CosineAnnealingLR(opt, cfg.epochs)
    best, best_state, bad, hist = float("inf"), None, 0, []
    for ep in range(cfg.epochs):
        model.train()
        acc, nb = {"par": 0.0, "obs": 0.0, "phys": 0.0, "total": 0.0}, 0
        for bt in torch.split(tr[torch.randperm(len(tr), generator=gen)], cfg.batch):
            opt.zero_grad()
            L, parts = losses(model, ctx, q[bt.to(device)], cfg)
            if torch.isfinite(L):
                L.backward()
                opt.step()
                for k in acc:
                    acc[k] += parts[k]
                nb += 1
        sched.step()
        model.eval()
        with torch.no_grad():
            vparts = {k: 0.0 for k in acc}
            chunks = torch.split(va, 2048)
            for ch in chunks:
                _, p = losses(model, ctx, q[ch.to(device)], cfg)
                for k in vparts:
                    vparts[k] += p[k] * len(ch) / len(va)
        hist.append(dict(epoch=ep, train={k: v / max(nb, 1) for k, v in acc.items()}, val=vparts))
        if log_every and ep % log_every == 0:
            print(ep, {k: f"{v:.3e}" for k, v in vparts.items()}, flush=True)
        if vparts["total"] < best - 1e-12:
            best, best_state, bad = vparts["total"], {k: v.detach().clone() for k, v in model.state_dict().items()}, 0
        else:
            bad += 1
            if bad >= cfg.patience:
                break
    model.load_state_dict(best_state)
    model.eval()
    return model, ctx, dict(history=hist, best_val_total=best, epochs_run=len(hist), n_synthetic=int(keep.sum()),
                            train_s=time.perf_counter() - started, stopped_early=len(hist) < cfg.epochs)

def robust_noise_var(q, t):
    """Per-row white-noise variance from the observations alone, valid on IRREGULAR time grids: robust scale of the
    time-weighted local interpolation residual (improved/methods.py noise_from_observations, 'local_interpolation_noise',
    batched; without its 1e-4 x range floor, so accurate observations can give zero)."""
    w = (t[1:-1] - t[:-2]) / (t[2:] - t[:-2])
    r = (q[:, 1:-1] - (1 - w) * q[:, :-2] - w * q[:, 2:]) / torch.sqrt(1 + (1 - w) ** 2 + w ** 2)
    mad = (r - r.median(-1, keepdim=True).values).abs().median(-1).values
    return (1.4826022185 * mad) ** 2

def blend(q, qj, t):
    """v2 (added after the synthetic preliminary check (1) failed; no GT involved): shrink the J-invariant estimate
    towards the observation with the weight of two estimators with independent errors,
    alpha = s_noise^2 / (s_noise^2 + s_pred^2), s_pred^2 = max(mean (q - qj)^2 - s_noise^2, 0).
    Accurate observations (s_noise -> 0) give alpha -> 0, i.e. no correction."""
    sn2 = robust_noise_var(q, t)
    d2 = ((q - qj) ** 2).mean(-1)
    sp2 = (d2 - sn2).clamp_min(0)
    alpha = torch.where(sn2 + sp2 > 0, sn2 / (sn2 + sp2).clamp_min(1e-300), torch.zeros_like(sn2))
    return q + alpha[:, None] * (qj - q), alpha

@torch.no_grad()
def infer(model, ctx, q_obs):
    """q_obs [B, N] (float64). Deterministic for a fixed checkpoint. q_hat is the v2 calibrated estimate; the
    J-invariant motion-head output is kept as q_hat_J."""
    q = q_obs.to(DT).to(ctx.tq.device)
    lI, lc = model.params(ctx, q)
    qj = model.motion(ctx, q)
    qhat, alpha = blend(q, qj, ctx.tq)
    return dict(log_I=lI, log_c=lc, q_hat=qhat, delta=qhat - q, alpha=alpha, q_hat_J=qj, delta_J=qj - q,
                P_obs=project(ctx, lI, lc, q), P_hat=project(ctx, lI, lc, qhat))

def save_checkpoint(path, model, ctx, cfg, seed, extra=None):
    torch.save(dict(state_dict={k: v.cpu() for k, v in model.state_dict().items()}, config=asdict(cfg), seed=seed,
                    n=ctx.N, extra=extra or {}), path)

def load_checkpoint(path, tf, tau, tq, device="cpu"):
    ck = torch.load(path, map_location="cpu", weights_only=False)
    cfg = Config(**ck["config"])
    ctx = Context(tf.cpu(), tau.cpu(), tq.cpu(), cfg).to(device)
    model = MLPJoint(ck["n"], cfg)
    model.load_state_dict(ck["state_dict"])
    return model.to(device).eval(), ctx, cfg
